//! Builds fixture responses from parsed flags and the evaluated range.

use crate::body::{Delivery, FixtureBody};
use crate::flags::{BadContentRange, EtagMode, Flags};
use crate::httpdate;
use crate::multipart;
use crate::range::{self, RangeOutcome};
use bytes::Bytes;
use http::{HeaderName, HeaderValue, Response, StatusCode, header};

/// XOR applied to the seed once a `mutable` resource has changed, so its bytes differ everywhere.
const MUTATED_SEED_XOR: u64 = 0x9E37_79B9_7F4A_7C15;
const OVERFLOW_NUMBER: &str = "99999999999999999999999";

/// The request parts that influence the response.
pub struct Target<'a> {
    /// True for HEAD.
    pub is_head: bool,
    /// Content seed from the path.
    pub seed: u64,
    /// Representation size from the path.
    pub size: u64,
    /// Raw `Range` header.
    pub range: Option<&'a str>,
    /// Raw `If-Range` header.
    pub if_range: Option<&'a str>,
    /// True once an `etag=mutable` resource has changed.
    pub mutated: bool,
}

impl Target<'_> {
    /// The seed of the bytes actually served (differs from `seed` once mutated).
    #[must_use]
    pub fn content_seed(&self) -> u64 {
        if self.mutated {
            self.seed ^ MUTATED_SEED_XOR
        } else {
            self.seed
        }
    }
}

/// A 200/206 response before its body is attached.
pub struct Plan {
    /// 200 or 206.
    pub status: StatusCode,
    /// First content offset served.
    pub start: u64,
    /// Number of body bytes served.
    pub len: u64,
    /// Every header except `Content-Length`.
    pub headers: Vec<(HeaderName, HeaderValue)>,
}

/// The result of planning: content to stream, or a complete early response.
pub enum Planned {
    /// Stream generated bytes.
    Content(Plan),
    /// A finished response (400 or 416).
    Early(Response<FixtureBody>),
}

/// A non-success response with a short plain-text body.
#[must_use]
pub fn error_response(status: StatusCode, message: &str) -> Response<FixtureBody> {
    let mut resp = Response::new(FixtureBody::from_bytes(Bytes::from(message.to_owned())));
    *resp.status_mut() = status;
    resp.headers_mut()
        .insert(header::CONTENT_TYPE, HeaderValue::from_static("text/plain"));
    if status == StatusCode::METHOD_NOT_ALLOWED {
        resp.headers_mut()
            .insert(header::ALLOW, HeaderValue::from_static("GET"));
    }
    resp
}

/// Sets a header from text; invalid values are skipped.
pub fn set(resp: &mut Response<FixtureBody>, name: HeaderName, value: &str) {
    if let Ok(v) = HeaderValue::from_str(value) {
        resp.headers_mut().insert(name, v);
    }
}

fn etag_value(flags: &Flags, target: &Target<'_>) -> Option<String> {
    let (seed, size) = (target.seed, target.size);
    match flags.etag {
        EtagMode::Strong => Some(format!("\"{seed}-{size}\"")),
        EtagMode::Weak => Some(format!("W/\"{seed}-{size}\"")),
        EtagMode::Mutable => Some(format!("\"{seed}-{size}-v{}\"", u8::from(target.mutated))),
        EtagMode::None => None,
    }
}

/// True when `If-Range` still matches the current validator (strong ETag or exact
/// Last-Modified). A Last-Modified equal to Date (`lm_eq_date`) is never strong.
pub fn if_range_matches(flags: &Flags, target: &Target<'_>) -> bool {
    let Some(candidate) = target.if_range else {
        return true;
    };
    let candidate = candidate.trim();
    strong_etag_matches(flags, target, candidate) || last_modified_matches(flags, candidate)
}

fn strong_etag_matches(flags: &Flags, target: &Target<'_>, candidate: &str) -> bool {
    etag_value(flags, target)
        .filter(|e| !e.starts_with("W/"))
        .as_deref()
        == Some(candidate)
}

fn last_modified_matches(flags: &Flags, candidate: &str) -> bool {
    !flags.lm_eq_date && flags.last_modified.as_deref() == Some(candidate)
}

pub(crate) fn outcome(flags: &Flags, target: &Target<'_>) -> RangeOutcome {
    match target.range {
        Some(raw) if flags.ranges && if_range_matches(flags, target) => {
            range::evaluate(raw, target.size)
        }
        _ => RangeOutcome::Full,
    }
}

pub(crate) fn metadata(flags: &Flags, target: &Target<'_>) -> Vec<(HeaderName, HeaderValue)> {
    let mut out: Vec<(HeaderName, HeaderValue)> = Vec::new();
    let mut put = |name: HeaderName, value: &str| {
        if let Ok(v) = HeaderValue::from_str(value) {
            out.push((name, v));
        }
    };
    put(header::CONTENT_TYPE, "application/octet-stream");
    if flags.ranges {
        put(header::ACCEPT_RANGES, "bytes");
    }
    if let Some(etag) = etag_value(flags, target) {
        put(header::ETAG, &etag);
    }
    if flags.lm_eq_date {
        let now = httpdate::now();
        put(header::DATE, &now);
        put(header::LAST_MODIFIED, &now);
    } else if let Some(lm) = &flags.last_modified {
        put(header::LAST_MODIFIED, lm);
    }
    if flags.gzip_header {
        put(header::CONTENT_ENCODING, "gzip");
    }
    if let Some(cd) = flags
        .content_disposition
        .as_deref()
        .and_then(|b| HeaderValue::from_bytes(b).ok())
    {
        out.push((header::CONTENT_DISPOSITION, cd));
    }
    out
}

/// The `Content-Range` value for a 206, corrupted per `bad_cr` when requested.
fn content_range(bad: Option<BadContentRange>, start: u64, len: u64, total: u64) -> String {
    let end = start.saturating_add(len).saturating_sub(1);
    match bad {
        None => format!("bytes {start}-{end}/{total}"),
        Some(BadContentRange::Start) => {
            format!("bytes {}-{end}/{total}", start.saturating_add(1))
        }
        Some(BadContentRange::End) => format!("bytes {start}-{}/{total}", end.saturating_add(1)),
        Some(BadContentRange::Total) => {
            format!("bytes {start}-{end}/{}", total.saturating_add(1))
        }
        Some(BadContentRange::Syntax) => "bytes garbage".to_owned(),
        Some(BadContentRange::Inverted) => {
            format!("bytes {}-{start}/{total}", end.saturating_add(1))
        }
        Some(BadContentRange::GeTotal) => format!(
            "bytes {total}-{}/{total}",
            total.saturating_add(len).saturating_sub(1)
        ),
        Some(BadContentRange::Overflow) => {
            format!("bytes {start}-{OVERFLOW_NUMBER}/{OVERFLOW_NUMBER}")
        }
    }
}

/// Decides status, range and headers for a validated GET/HEAD request.
///
/// A 400 is returned when `cd` is not a valid header value; a 416 for an unsatisfiable range.
#[must_use]
pub fn plan(flags: &Flags, target: &Target<'_>) -> Planned {
    if flags
        .content_disposition
        .as_deref()
        .is_some_and(|b| HeaderValue::from_bytes(b).is_err())
    {
        return Planned::Early(error_response(StatusCode::BAD_REQUEST, "invalid cd flag"));
    }
    let (status, start, len) = match outcome(flags, target) {
        RangeOutcome::Full => (StatusCode::OK, 0, target.size),
        RangeOutcome::Partial { start, end } => {
            let len = end - start + 1;
            let shortened = flags.short206.map_or(len, |n| len.saturating_sub(n).max(1));
            (StatusCode::PARTIAL_CONTENT, start, shortened)
        }
        RangeOutcome::Unsatisfiable => return Planned::Early(unsatisfiable(target.size)),
    };
    let mut headers = metadata(flags, target);
    if status == StatusCode::PARTIAL_CONTENT {
        let value = content_range(flags.bad_cr, start, len, target.size);
        if let Ok(v) = HeaderValue::from_str(&value) {
            headers.push((header::CONTENT_RANGE, v));
        }
    }
    Planned::Content(Plan {
        status,
        start,
        len,
        headers,
    })
}

/// The 416 answer: `Content-Range: bytes */size`.
#[must_use]
pub fn unsatisfiable(size: u64) -> Response<FixtureBody> {
    let mut resp = error_response(StatusCode::RANGE_NOT_SATISFIABLE, "range not satisfiable");
    set(&mut resp, header::CONTENT_RANGE, &format!("bytes */{size}"));
    resp
}

/// The delivery options carried by the flags.
#[must_use]
pub fn delivery(flags: &Flags) -> Delivery {
    Delivery {
        slow_bps: flags.slow_bps,
        drop_after: flags.drop_after,
        stall_after: flags.stall_after,
        slow_from: flags.slow_from,
    }
}

/// Builds the response for a validated GET/HEAD request.
pub fn build(flags: &Flags, target: &Target<'_>) -> Response<FixtureBody> {
    if flags.multipart
        && let Some(resp) = multipart::try_build(flags, target)
    {
        return resp;
    }
    let plan = match plan(flags, target) {
        Planned::Content(plan) => plan,
        Planned::Early(resp) => return resp,
    };
    let body = if target.is_head {
        FixtureBody::empty()
    } else {
        FixtureBody::generated(
            target.content_seed(),
            plan.start,
            plan.len,
            flags.content_length,
            delivery(flags),
        )
    };
    let mut resp = Response::new(body);
    *resp.status_mut() = plan.status;
    for (name, value) in plan.headers {
        resp.headers_mut().insert(name, value);
    }
    if flags.content_length {
        set(&mut resp, header::CONTENT_LENGTH, &plan.len.to_string());
    }
    resp
}
